      "EN2: For the purpose of this achievement standard, materials are groups of substances which share structural similarities. Types of materials are limited to: molecular substances, such as water and iodine; metallic solids, such as lead pipe, magnesium alloy wheels, and copper wire; ionic materials, such as nitrate fertilizers and salt; natural and synthetic polymers, such as DNA, proteins, and non-stick coatings on cookware; covalent networks, such as diamond and graphite.",
