      "Codes (2024 and 2025, same wording): N0 no response, no relevant evidence. N1 'Very little Achievement level evidence.' N2 'Some Achievement level evidence, partial explanations.' A3 'Most Achievement level evidence.' A4 'Nearly all Achievement level evidence.' M5 'Some Merit level evidence.' M6 'Most Merit level evidence.' E7 'Excellence level evidence. One part may be weaker.' E8 'All points covered at Excellence level.'",
      "Read the levels against the parts: Achievement evidence lives in (a) relationships and (b) the direct effect; Merit evidence in (c) and (d) flow-on effects and their impact on relationships; Excellence evidence in (e) and (f) justified decisions and their consequences for the entities.",
      "Schedule sample evidence (2025): (a) customer–supplier transport revenue both ways, taxes and GST funding services and transfer payments, loans and deposits earning the bank interest; (b) Leota's demand and revenue fall; (c) lower income for the whānau and changes to deposits, interest or overdrafts; (d) less income tax and GST and more transfer payments, so less government spending on contracts and subsidies; (e)/(f) consequences for each named entity plus reasons for the decision (e.g. cutting costs, diversifying, creating local jobs).",
      "The sample evidence is illustrative; any accurate, reasoned flow that fits the case study counts."
