      "2025, commentary: most understood interdependence and separated direct from flow-on effects well. A common error was the Government's role (supplying power to households, raising tax rates at short notice, receiving tariffs or export revenue). The whānau–bank relationship was explained better than Government–business. More candidates reached Excellence than in 2024, but many still left out future income or profit, purchasing power, or the ability to deliver a service.",
      "2024, Achievement: same profile as 2025 (two participants relying on each other, correct terms, direct effect on Delectable Donuts as higher sales, revenue or profit).",
