      "2025, Not Achieved: no reference to a financial model; inappropriate, unclear or incomplete actions; no discussion of pūtake; actions without the factor's effect, or the reverse.",
      "2025, commentary: moving from the 2024 digital report to an exam had little effect on results. Almost all candidates used the case study; those using their own organisation often lacked the detailed evidence needed for Merit or Excellence. Candidates must use at least one model explicitly and accurately. Actions must address the chosen factor. Answers must focus on financial viability, not just sales or costs. 'Pūtake' and 'puutake' are both accepted.",
