     "notes": [
      "EN1: Demonstrate understanding of usability in human-computer interfaces involves: describing the purpose of human-computer interfaces; describing usability principles and their use in human-computer interfaces.",
      "EN1: Examine the usability of human-computer interfaces involves: explaining how usability principles have been applied in human-computer interfaces; explaining the usability of human-computer interfaces in terms of usability principles.",
      "EN1: Evaluate the usability of human-computer interfaces involves: comparing the usability of human-computer interfaces; applying usability principles to suggest improvements to human-computer interface usability.",
      "EN2: For the purposes of this achievement standard, the usability of human-computer interfaces can be understood in terms of usability principles. Examples of usability principles could include: mātāpono Māori such as accurate use of te reo Māori, support for te reo Māori in tools such as spell checking, support for expression of tikanga and mātauranga Māori; usability concepts such as internal and external consistency, accessibility; Nielsen's usability heuristics."
     ],
     "examFormat": [
      "2026 change: none found. The 2026 specification repeats the 2025 format: an end-of-year online digital examination on a computer, short and extended answers, NZQA resources supplied in the exam (including a list of Nielsen's heuristics), usability principles drawn from mātāpono Māori, Nielsen's heuristics and usability concepts (internal and external consistency, accessibility), and no more than 800–1200 words.",
      "Candidates study an interface of their OWN choice before the exam and write about it in Part C.",
      "Five parts, A to E, in both 2024 and 2025: A short answers (definitions, matching, mātāpono Māori); B identifying principles in screenshots of real websites; C the candidate's studied interface; D one of two design scenarios (one is Māori-focused); E comparing two real interfaces shown in SILENT videos (play, pause and restart allowed) and suggesting improvements. Candidates are told to read all parts first.",
      "The papers give no time allowance. The cover says aim for no more than 1200 words in total.",
      "Resource A (mātāpono Māori, 2025) covered accurate te reo Māori including tohutō and macrons, spell-checking and word prediction in te reo, manaakitanga, rangatiratanga and whanaungatanga. Resource C covered internal and external consistency, and accessibility."
     ],
