     "assessmentReport": [
      "2025, Achievement: identified interface features that showed usability principles and named the principle, explained why usability principles matter, identified and described 3–4 principles correctly from the Part B screenshots, and matched the definitions in Part A with a correct example of match between system and real world.",
      "2025, Merit: explained features related to a principle in the chosen interface and linked them to its purpose, related principles to efficiency of use, and identified specific implementations for the Part D scenario and how they would support users.",
      "2025, Excellence: compared two interfaces on the SAME principles (e.g. how both used error prevention when creating an account), identified improvements each linked to a principle, communicated concisely, and clearly separated commonly confused principles.",
      "2025, Not Achieved: described interface features without referring to usability principles, got principles wrong, confused similar principles, or used the literal meaning of a principle's name (e.g. 'user control and freedom' as moving around a website freely).",
      "2025, commentary: commonly confused pairs were user control and freedom versus flexibility and efficiency of use, and error prevention versus error recovery. Accessibility answers often mentioned only language, or only font size, contrast and screen readers. Choosing the school website or a self-designed interface for Part C often disadvantaged candidates because they lacked dynamic features. Candidates who blended mātāpono Māori with heuristics did well. Some could not give four different heuristics in Part A.",
      "2024, Achievement: knew a range of principles and gave examples of implementation, but explanations of accessibility and of why usability matters were weak and broad.",
      "2024, Merit: explained how at least two principles were effectively implemented in the chosen interface with reference to user experience, and how a designed interface would include two principles and how each would help the user. The step from A to M was explaining how a principle improved the interface, not just naming it.",
      "2024, Excellence: identified common principles across the video pairs, judged which interface used them better and explained how, and gave multiple improvements each linked to a heuristic with how it would be implemented. Candidates who gave only one suggestion when several were asked for could not gain higher marks.",
      "2024, Not Achieved and commentary: weak or confused knowledge of principles, or generic descriptions of performance without principles. Some candidates wrote about an interface from elsewhere in the exam, the NZQA exam interface, or a generic food-ordering site. Very few chose the Māori scenario in Part D, often answering it poorly; some designed whole systems beyond scope."
     ],
