     "assessmentReport": [
      "2025 (portfolio), Achievement: showed a design process with a genuine need or opportunity, potential users and requirements, generated ideas and a completed design, and described how manaakitanga or kaitiakitanga was used authentically. Feedback was collected but did not clearly improve the design, and written reasons for decisions were limited.",
      "2025, Merit: used feedback effectively to make at least two clear improvements and explained how at least one design decision improved the design's quality, with different examples. Merit scripts often did not refer back to the requirements when justifying fitness for purpose.",
      "2025, Excellence: a structured process from ideas to refinement to a detailed final design that showed how the outcome would look and work; specific examples from their own design; decisions justified with evidence (research, feedback, design principles) and linked to the need, end users and requirements; explained WHY key changes were made and their impact.",
      "2025, Not Achieved: wrote about developing the outcome rather than designing it, had no clear need or opportunity, named users without requirements, did not address manaakitanga or kaitiakitanga, gave too little evidence of ideas and a final design, used AI or internet images as design evidence, or proposed outcomes too simple for Level 6.",
      "2025, commentary: design was often confused with development (evidence from 92004 or 92005). Feedback was often vague or used to choose an idea rather than improve the design. The final evaluation was a common weakness. Manaakitanga and kaitiakitanga were often confused or treated as the design's context rather than practices shown through design decisions; manaakitanga should go beyond 'respecting feedback'. Heavily templated or teacher-driven briefs limited genuine decisions.",
      "2024, Excellence: clearly distinguished designing from creating, listed requirements as bullet points and explained how each was met, and linked decisions back to end users and requirements. 2024, Merit: two feedback-driven improvements with specific examples, but fitness for purpose often repeated improvements instead of showing how requirements were met.",
      "2024, commentary: requirements should be written as what the design must achieve, not as things already done. Database designs need an ER diagram; program designs need flowcharts or pseudocode. EN2 (manaakitanga and/or kaitiakitanga) was often answered with only one example or about the design's content rather than the design or process."
     ],
