   "discipline": "Both Level 1 English exams are judged on the quality of understanding. Answers move from describing (A), to explaining how aspects work together (M), to discussing the relationship between aspects and the writer's purpose or wider context (E), always with specific evidence from the text. 91925 is one essay-style response to a chosen question on a studied text, marked holistically with one code out of 8. 91927 is three short responses to unseen texts, each coded N0–E8 and totalled out of 24. Length, plot summary, definitions of techniques and learned essays that do not answer the question are never the criterion.",
   "parallelHint": "for 91925, a different question or statement on the student's studied text (or a different studied text), still asking for two specific aspects and a personal or wider connection; for 91927, three different unseen written texts of a similar length and difficulty, including at least one poem and at least one text reflecting a Māori context, each with one 'How does the writer help us understand…?' question",
