      "End-of-year ONLINE DIGITAL examination. Candidates select ONE option from a range of questions and/or statements and write one concise response with reference to aspects of the text. Planning spaces are not marked; responses must be in English.",
      "The student brings their own studied text(s) from memory: written, visual or oral, from Aotearoa NZ, the Pacific or the world. More than one studied text may be used.",
