   "discipline": "Both Level 1 Geography exams are marked holistically. Markers read the whole booklet and give one score from 0 to 8, judged on the step from describe (A) to explain (M) to examine (91934) or evaluate (91935) (E). For 91934 the score depends on describing a natural process as a SEQUENCE of events, linking it to the phenomena it formed, and tracing impacts and future implications for people. For 91935 it depends on separating viewpoint from perspective and judging how far they inform a decision. In both, relevant evidence (place names, figures, resource detail) and accurate geographic terminology carry the answer. Prepared case-study recall that does not answer the question, and copied resource text, earn little.",
   "parallelHint": "for 91934, a different unfamiliar environment shaped by a different combination of natural processes (for example a glaciated valley instead of a river mouth), and a different case study environment; for 91935, a different geographic challenge in a different part of the wider Pacific region (Micronesia, Melanesia or Polynesia, including Aotearoa New Zealand), with different named people and options",
