   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which covers external examinations. 91934 and 91935 are both end-of-year examinations on printed paper in 2026 (2026 Assessment Specifications).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards, and school-marked portfolio work verified by NZQA. There is NO Level 1 exclusion. 91935 is approved for literacy (NCEA Education page for 1.4), but it is a subject standard, not a dedicated co-requisite standard, so it is not excluded on that ground.",
    "A2024/5: an external standard is eligible when it is a point-in-time assessment on a date NZQA defines, with one assessment event per year. A2024/5 does not name either Geography standard. Both are single November exams in 2026 (Tuesday 17 November, 2:00pm session, NZQA timetable), so they meet the test. This is an inference from the criteria, not an NZQA statement.",
    "91934 history: in 2024 it was a submitted report (Part A on a different environment chosen by the student, Part B on the course case study) (2024 Assessment Report). Since 2025 it has been an examination. Practice evidence modelled on the 2024 report, with resources the student chose or prepared, does NOT match the 2026 format and conditions.",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence, gathered from a practice assessment that matches the format and conditions of the external assessment, and submitted before the November examinations.",
    "For 91934 that means: a printed booklet, a choice of ONE of three unseen environments (map and/or photographs) in Section One, and the student's own case study in Section Two, written under supervision without notes. For 91935 it means: a pre-release resource given to students ahead of the practice exam (NZQA releases its real one in Term 4, Week 1), plus additional unseen resources in the exam, with a combined resource booklet.",
    "For 91935 the real 2026 pre-release arrives in Term 4, Week 1, which is after most schools run practice exams. A practice exam must therefore use a different challenge and its own pre-release, set by the school. It cannot use NZQA's 2026 pre-release as unseen evidence after the fact.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader should verify it. Practice exams may be based on modified papers from previous years.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result. Not Achieved is a valid derived grade."
   ],
