        "(i) Name TWO processes that would have operated to shape the environment shown.",
        "(ii) Label the topographic map and/or photograph(s) to show a range of features shaped by those processes.",
        "(iii) Explain how two of the features labelled in (ii) were formed by the processes named in (i), referring to the resource and using geographic terminology.",
        "Section Two, case study environment named by the candidate. (iv) Explain how TWO natural processes in the case study have influenced cultural features (e.g. transport routes, buildings, land use, economy, infrastructure), with case study evidence and terminology.",
        "(v) Examine how the natural processes in the case study environment may have implications for people in the future. Maps and/or diagrams may be included."
