   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which includes external examinations. 92010 and 92011 are both end-of-year online digital examinations in 2026 (2026 Assessment Specifications).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards (32403, 32405, 32406, 32412, 32413, 32415), and school-marked portfolio work verified by NZQA. There is no Level 1 exclusion, and neither Health standard is named as ineligible.",
    "A2024/5: a new standard is eligible when it is a point-in-time assessment with the date set by NZQA and one assessment event per year. A2024/5 does not name Health Studies. Both 92010 and 92011 are single November exams in 2026, so they meet this test. This is my inference from the criteria.",
    "92011 history: in 2024 it was NOT an exam. It was a school-scheduled report, pre-released in Term 3 Week 1, written in class over a recommended four hours and submitted as a PDF by 30 October 2024 (2024 specification). Since 2025 it has been an end-of-year exam. Evidence modelled on the 2024 report does NOT match the 2026 format and conditions.",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence from a practice assessment that matches the format and conditions of the external assessment, and they must be submitted before the November examinations. EmaiLink August 2026 repeats that practice exams for derived grades must match the external format and conditions and be quality assured.",
    "For both standards that means: an unseen scenario and resource booklet, one multi-part question, all parts answered under supervision, no notes, and the answer must use the scenario. For 92011 the answer must also draw on at least one underlying concept (attitudes and values, health promotion, socio-ecological perspectives).",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader should verify it. Practice exams may be based on modified papers from previous years.",
    "2026 Rules change summary (as recorded for this pilot): derived grades are approved only after the exam cycle is complete, the student gets the better of the derived grade and the exam result, and Not Achieved is a valid derived grade."
   ],
