      "The paper is marked as a whole (holistic): one score code from 0 to 8 for Question One, covering every part together. The exemplar scripts show a single code for Question One (e.g. A4) that is also the total. Parts are not scored separately and added.",
      "Cut scores (2024 and 2025 schedules): Not Achieved 0–2, Achievement 3–4, Merit 5–6, Excellence 7–8.",
      "N0: no response, no relevant evidence. N1: sparse information, some answers not attempted. N2: some relevant material, but not enough evidence for Achievement.",
      "A3: the responses generally meet Achievement but may be inconsistent across the criteria. A4: the responses meet Achievement. M5/M6 and E7/E8 follow the same pattern ('generally meet, with some inconsistency' versus 'meet').",
      "The schedule maps each part to the criteria. 2025: (a) Achievement only (describes TWO factors that negatively influence Sara's hauora); (b) A describes at least two factors short and long term, M explains how and why they interrelate, E draws conclusions on how they interrelate short and long term; (c) A at least two factors, M explains why they lead to unintended consequences, E evaluates the implications; (d) A at least two factors, M explains how and why they affect hauora, E evaluates their significance for hauora and future participation.",
      "The sample evidence is not exhaustive. Answers are not judged solely on the listed evidence."
