   "slug": "history",
   "discipline": "Both Level 1 History exams are marked holistically. Markers read the whole response and give one score from 0 to 8, judged against the step from describe (A) to explain (M) to examine (E). The score depends on how clearly the student links the concept or perspective to specific historical evidence (names, dates, statistics, short quotes) and explains how and why, not on narrative. Length, retelling the event in order and textbook definitions are never the criterion: NZQA states that assessment is based on the quality of the response, not its length.",
   "parallelHint": "a different historical context of significance to Aotearoa New Zealand (a different event, place, person or movement, for example the 1975 Land March instead of Bastion Point), or for 92027 a different pair of individuals or groups in a different context",
