   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work. This covers external examinations and eligible submitted subjects, portfolios, CAAs and TAPā. 92026 and 92027 are both end-of-year examinations in 2026, delivered online (2026 Assessment Specifications).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards (32403, 32405, 32406, 32412, 32413, 32415), and school-marked portfolio work verified by NZQA. There is NO Level 1 exclusion. A subject standard approved for literacy (such as 92027) is not one of the dedicated co-requisite standards, so it is not excluded on that ground.",
    "A2024/5: a new standard is eligible for a derived grade when it is a point-in-time assessment with one assessment event per year. Standards whose assessment schools manage over time, or which allow reassessment (e.g. the co-requisite standards 32403/32405/32406), are not eligible. 92026 and 92027 are both single November exams in 2026, so they meet this test. This is my inference from the criteria: NZQA does not name History in the circular.",
    "92027 history: in 2024 it was a school-managed report written over time (recommended 4 hours, about 1200 words or 4 minutes of audio or video). Since 2025 it has been an examination. Evidence modelled on the 2024 take-home report does NOT match the 2026 format and conditions (2024 and 2025 Assessment Reports; 2026 specification).",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence. That evidence must be a practice assessment matching the format and conditions of the external assessment, and grades must be submitted before the November examinations. EmaiLink August 2026 repeats that practice exams for derived grades must match the external format and conditions and be quality assured.",
    "For 92026 that means a resource booklet NOT seen before the practice exam, ONE specified concept applied to the booklet, and TWO specified concepts applied to a studied context using the student's own evidence. For 92027 it means no resource booklet, with the student's own studied context and two differing individuals or groups. In both, the student writes under supervision, in paragraphs, without notes.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader (panel marking or a colleague checking boundary scripts) should verify it. Practice exams may be based on modified papers from previous years.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result. Not Achieved is a valid derived grade, and NZQA records a school-reported N as V."
   ],
