     "notes": [
      "EN1: Demonstrate understanding (Achieved) involves describing historical concepts within different contexts of significance to Aotearoa New Zealand, and including relevant historical evidence in the description.",
      "EN1: Explain (Merit) involves explaining historical concepts and their relevance within different contexts of significance to Aotearoa New Zealand, and using historical evidence to support the explanation.",
      "EN1: Examine (Excellence) involves examining historical concepts and their relevance ACROSS different contexts of significance to Aotearoa New Zealand, and using historical evidence to develop the explanation.",
      "EN2: Historical concepts are used to think critically about the past. Examples include mana and causation. (For the exam, the 2026 specification limits the list to mana, whakapapa, tūrangawaewae, cause and effect.)",
      "EN3: Contexts of significance to Aotearoa New Zealand are contexts that either involve or influence New Zealanders. For this standard, the student engages with an Aotearoa New Zealand context and at least one further context. That further context could be another Aotearoa New Zealand context, an international context involving New Zealanders, or an international context that includes an event influencing New Zealanders.",
      "EN4: Historical evidence includes specific historical detail such as names (of people, places or events), dates, statistics, figures, short quotes, or a combination of these, that relates to and helps the response.",
      "A2025/10: definitions of the concepts are no longer printed in the resource booklet (they were in 2023 and 2024). Candidates must show understanding of the concept in context but are NOT expected to give a verbatim definition."
     ],
     "examFormat": [
      "2026 (specification published October 2025): an end-of-year examination in online digital format. It is a single question with multiple parts, each needing paragraph responses. Planning spaces are not marked, and quality counts, not length.",
      "UNFAMILIAR context: candidates get a resource booklet of primary and secondary historical sources. The resources are NOT released before the exam. Candidates show understanding of ONE specified historical concept in the context of the resource material.",
      "FAMILIAR context: candidates also show understanding of TWO historical concepts in a familiar (studied) context, using evidence OTHER than the resource booklet. The concepts are specified from the list: mana, whakapapa, tūrangawaewae, cause, effect. The specification does not say whether the familiar-context concepts may repeat the booklet concept.",
      "THIS IS A CHANGE from 2024 and 2025. In those years, parts (a) and (b) applied TWO specified concepts to the booklet, and part (c) applied ONE of those two (the student's choice) to a studied context. The 2025 specification (March 2025) described two concepts in each context, but the 2025 paper asked for only one in the studied context.",
      "The studied context must be of significance to Aotearoa New Zealand (EN3). It may be international if it involves or influenced New Zealanders. Reports show the Birmingham Campaign, Kristallnacht and 9/11 were used, with mixed success depending on how well the concept fitted.",
      "The 2024 paper gave candidates stimulus material at the start of Term 4 and printed concept definitions in the booklet. For 2025 and 2026 the definitions are gone, and the 2026 specification says the resources are not released beforehand.",
      "The papers give no time allowance or word guidance. The 2024 and 2025 booklets had about 3 pages of answer space, and the 2025 booklet ran to 8 pages including extra space."
     ],
     "markingModel": [
      "The paper is marked HOLISTICALLY: the schedule has one set of score codes for the whole response, covering every part together. The parts are not scored separately and added up.",
      "Cut scores (2024 and 2025 schedules): Not Achieved 0–2, Achievement 3–4, Merit 5–6, Excellence 7–8. The total is the single code.",
      "N0: no response or no relevant evidence. N1: attempts to describe concepts across different contexts, but no evidence. N2: attempts to describe them, but the evidence is limited or inaccurate, OR only one concept is described in context.",
      "A3: describes the concepts using the provided Aotearoa NZ context AND a studied historical context, with some relevant evidence. A4: as A3, with relevant evidence (more complete).",
      "M5: explains the concepts and their relevance in the provided context and the studied context, with relevant evidence supporting the explanation. M6: as M5, with a RANGE of relevant evidence fully supporting the explanation.",
      "E7: examines the concepts and their relevance ACROSS the provided and studied contexts, with relevant evidence fully developing the explanation. E8: as E7, with a range of relevant, WELL-CONSIDERED evidence fully developing the explanation.",
      "The appendix sample evidence is described as not exhaustive. Any accurate, relevant evidence from the booklet (or, for the studied context, from the student's own learning) counts.",
      "For a 2026-format practice paper, read the codes across all three applications (one booklet concept and two studied-context concepts). A response that handles only one concept, or only one of the two contexts, is capped at N2 (per the N2 descriptor)."
     ],
