       "year": "2024",
       "questions": [
        "Resource context: Ngā Tamatoa and Te Petihana Reo Māori (the Māori Language Petition), 1972. Sources A–E: te reo in decline, the creation of Ngā Tamatoa (1970), the petition at Parliament, 1972 news footage, and the 50-year reunion (2022). The booklet printed definitions of cause, effect, mana, tūrangawaewae and whakapapa.",
        "(a) How does the resource context demonstrate the historical concept of cause? Support with evidence from the sources.",
        "(b) How does the resource context demonstrate the historical concept of mana? Support with evidence from the sources.",
        "(c) Name a studied context of significance to Aotearoa NZ, tick ONE concept (cause or mana), and explain how the studied context demonstrates it. The schedule's sample used the 1975 Land March and mana."
       ],
