     "assessmentReport": [
      "2025, Achievement: answered all three parts, described the concepts and where they appeared with limited explanation, relied heavily on quoting or paraphrasing sources followed by a brief description, used generic or limited evidence (especially in (c)), and read tūrangawaewae simply as belonging or a significant place, without whakapapa, mana or rights to land.",
      "2025, Merit: explained both concepts in the resource material and the studied context, linked a range of evidence to show HOW it demonstrated the concept, read Source D correctly (tūrangawaewae the concept versus Tūrangawaewae Marae the place), and showed depth through, for example, short- and long-term effects.",
      "2025, Excellence: thorough, nuanced understanding across ALL three parts. These candidates selected only the most relevant evidence rather than summarising whole sources, made the link explicit ('This relates to tūrangawaewae because…'), built the argument first and then supported it with evidence, and handled tūrangawaewae with sophistication (whakapapa, mana, identity, reciprocal people–land relationships). They were consistent, planned and logical, with little repetition.",
      "2025, Not Achieved: did not attempt all parts (especially (c)), chose a concept that did not suit the context, misunderstood tūrangawaewae, wrote narrative with little reference to the concept, gave limited, inaccurate or no evidence, misread Source D, or used ill-fitting contexts such as Mount Erebus for tūrangawaewae.",
      "2025, commentary: part (c) was the hardest. The 1975 Land March was popular but a poor fit for tūrangawaewae (effect suited it better). Disaster contexts, Kemp's Deed, and the Dawn Raids/Polynesian Panthers often lacked conceptual depth for tūrangawaewae. The event must not be confused with the concept (the building of Tūrangawaewae Marae is not the concept). Higher responses showed concept-first thinking.",
      "2024, Achievement: descriptive or narrative answers, often one source per answer in (a) and (b), 'the source shows/says' phrasing, generic evidence in (c), sources copied and paraphrased for meaning rather than significance, one concept done more thoroughly than the other.",
      "2024, Merit: a range of sources, 'this led to / this shows… because…' phrasing, consideration of long- and short-term causes or mana tūpuna, and clear examples of mana enhanced, diminished or gained. A source-by-source approach, or describing sources and then adding a closing link sentence, held responses at Merit.",
      "2024, Excellence: range of relevant, well-considered evidence across all three parts. These candidates extracted only the most relevant information, started from their own ideas, considered several aspects of the concept, drew conclusions beyond the sources and examined the sources critically. Connecting to other concepts (tūrangawaewae, tuakiri) or to big ideas was not required but showed examining across contexts.",
      "2024, Not Achieved: missing parts, used the BOOKLET context for (c) instead of a studied context, copied the booklet definitions without unpacking them, gave little or no evidence in (c), narrated the event without the concept, or wrote about consequences when the concept was cause.",
      "2024, commentary: using more of the provided sources helped in (a) and (b). Short-term and long-term cause gave useful structure. In (c), mana sat poorly with non-NZ contexts such as Czechoslovakia, Kristallnacht and 9/11, where cause fitted better. For the Springbok Tour, students had to be clear whether they meant the tour or the protests. 'The Civil Rights movement' was too broad (choose the Birmingham Campaign, the Montgomery Bus Boycott or similar). Disaster contexts often ended with a tacked-on 'this showed mana'. The Land March, Bastion Point, and the Polynesian Panthers/Dawn Raids worked well."
     ],
