   "discipline": "Both Level 1 Mathematics and Statistics exams are marked question by question. Each of the three questions gets one score code (N0–E8) from how many pieces of Achievement (u), Merit (r) and Excellence (t) evidence its parts show, and the three codes are totalled out of 24. In 91946 the evidence is contextual statistical and mathematical literacy: features described in context, numerical evidence, justified judgements and, for Excellence, evaluation of variation, assumptions and limitations. In 91947 it is correct mathematics shown through working: a correct answer with no working is 'Correct Answer Only' and gains u at best, and graphical calculator output alone earns no credit.",
