      "2025, Not Achieved: inaccurate percentage or fraction calculations, no use of the resource-booklet context, could not identify or describe relevant features when comparing samples (compared point estimates to reach conclusions), did not describe or interpret the time series or the relationship between two variables, or did not attempt enough parts.",
      "2025, commentary: gaps in basic number skills and in reading time-series graphs; some candidates were unfamiliar with working from a resource booklet; multifaceted questions were challenging; many did not know how to respond when a 'personal worldview' was asked for. Level 6 content is assessed, but lower-level curriculum knowledge is expected.",
      "2024 (report format), Achievement: generalised answers to the prompts not justified from the resources, Section B lacking detail, reliance on one resource, comparisons of only one factor.",
      "2024, Merit: detailed answers using evidence from the resource booklet with justification, quantitative evidence (averages, ratios, relative percentages), a described and interpreted scatter-plot trend, multiple advantages and disadvantages compared.",
      "2024, Excellence: considered limitations and assumptions, drew on personal viewpoints and background research, used multiple resources, made three or more well-supported statements or comparisons, identified complex patterns.",
      "2024, Not Achieved: struggled to interpret the resources, ignored the prompts, relied on own knowledge rather than the graph features, used wrong units or variable references."
