   "discipline": "Both Level 1 PESS exams are printed papers with three questions. Each question gets its own score code (N0–E8) by counting Achievement, Merit and Excellence evidence points, and the three codes are totalled out of 24. Achievement is accurate description (labelled diagrams, correct definitions, single-step calculations), Merit is explanation that links science ideas to the observation or the change (with correct units on calculations in 92047), and Excellence integrates several ideas into a discussion of how an effect varies by latitude or time (92046) or of the implications of a change (92047). Vague statements, unexplained numbers and length are never the criterion.",
