   "derivedGradeNotes": [
    "2026 Rules, Schedule 2 cl. 3(2): derived grades are available only where NZQA marks the work, which covers external examinations. 92046 and 92047 are both end-of-year PRINTED PAPER examinations in 2026 (2026 Assessment Specifications).",
    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards (32403, 32405, 32406, 32412, 32413, 32415), and school-marked portfolio work verified by NZQA. There is no Level 1 exclusion.",
    "A2024/5: a new standard is eligible for a derived grade when it is a point-in-time assessment with one assessment event per year. Both standards are single November exams in 2026, so they meet this test. This is an inference from the criteria: NZQA does not name them in the circular.",
    "92046 history: the 2024 Assessment Report describes it as a school-managed submission (three questions using prompts and the candidate's own knowledge). It was a printed-paper exam in 2025 and is again in 2026. A practice task run in the 2024 school-managed way should be checked against the 2026 exam conditions.",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence from a practice assessment that matches the format and conditions of the external assessment, submitted before the November examinations. EmaiLink August 2026 repeats this.",
    "For both standards that means a supervised printed-paper practice exam of three questions with an approved calculator and no notes. For 92047 the formulae must be supplied in the paper (2026 specification), and for 92046 the supplied resources (graphs, tables, diagrams) are used with the student's own knowledge.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader should verify it. Practice exams may be based on modified papers from previous years.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result. Not Achieved is a valid derived grade, and NZQA records a school-reported N as V."
   ],
