   "discipline": "Both Level 1 Science externals are about the nature of science, not subject content, and each response gets ONE holistic score from 0 to 8 for the whole paper. 91922 is judged on the step from describing features of science (A), to explaining why each was significant (M), to discussing how they interacted (E), always with examples taken from the resource booklet. 91923 is judged on the step from describing the source, purpose, claim and science language or conventions (A), to explaining how those conventions support the claim (M), to evaluating how well they do (E). Recall of science facts, length and copying the resource are never the criterion: NZQA judges the level of understanding shown, not the wording.",
   "parallelHint": "a different science idea or communicated claim from a different resource, e.g. a different Aotearoa NZ or Pacific science idea for 91922 (such as kauri dieback research instead of seaweed-fed cattle), or a different product, article or website making a science-related claim for 91923 (such as a sunscreen advert instead of a personality-test site)",
