    "2026 Rules, Schedule 2 cl. 3(3): the exclusions are NZ Scholarship, standards NZQA has published as ineligible, the dedicated co-requisite literacy and numeracy standards (32403, 32405, 32406, 32412, 32413, 32415), and school-marked portfolio work verified by NZQA. There is no Level 1 exclusion.",
    "A2024/5: a new standard is eligible for a derived grade when it is a point-in-time assessment with one assessment event per year. Both standards are single November exams in 2026, so they meet this test. This is an inference from the criteria: NZQA does not name 91922 or 91923 in the circular.",
    "91923 history: in 2024 it was an over-time submitted report (material pre-released Term 3 Week 1, at most four A4 pages or four slides, about 4 hours suggested, submitted digitally by 30 October 2024). Since 2025 it has been an examination. Evidence modelled on the 2024 take-home report does NOT match the 2026 format and conditions (2024 specification; 2025 Assessment Report).",
    "2026 Rules, Schedule 2 cl. 4(1) and 4(3): grades must come from quality-assured, pre-existing, valid, authentic, standard-specific evidence from a practice assessment that matches the format and conditions of the external assessment, submitted before the November examinations. EmaiLink August 2026 repeats this.",
    "For 91922 that means an UNSEEN resource booklet on the development of a local (Aotearoa NZ or Pacific) science idea, with features of science drawn from the 2026 list. For 91923 it means an unseen booklet of communicated information containing science-related claims. In both, the student writes under supervision without notes, in short-sentence or paragraph answers.",
    "NZQA derived-grade QA page: the evidence must cover ALL criteria of the standard, it must be certain the work is the student's own, and a suitably qualified second reader should verify it. Practice exams may be based on modified papers from previous years, but for 91922 a 2024 or 2025 paper must be changed to use the 2026 features of science.",
    "2026 Rules change summary: derived grades are approved only after the exam cycle is complete. The student gets the better of the derived grade and the exam result. Not Achieved is a valid derived grade, and NZQA records a school-reported N as V."
